"use client";import {useEffect,useState}from"react";import type{Article}from"../../lib/article-content";export default function Articles(){const[a,setA]=useState<Article[]>([]);useEffect(()=>{fetch("/api/articles").then(r=>r.json()).then(setA)},[]);return <main className="orderPage" dir="rtl"><a className="back" href="/">← بازگشت به سایت</a><section className="section"><div className="title"><small>مجله رایامهر</small><h1>مقالات آموزش زبان کودک</h1></div><div className="grid packages">{a.map(x=><article className="card" key={x.id}><div className="cardImg"><img src={x.image} alt={x.title}/></div><h3>{x.title}</h3><p>{x.excerpt}</p><a className="button" href={`/articles/${x.slug}`}>مطالعه مقاله</a></article>)}</div></section></main>}
